CREATE TABLE mutation_author (id integer PRIMARY KEY, name text NOT NULL);
CREATE TABLE mutation_item (
    id integer GENERATED BY DEFAULT AS IDENTITY (START WITH 100) PRIMARY KEY,
    owner_id integer NOT NULL DEFAULT 1 REFERENCES mutation_author(id),
    title text NOT NULL DEFAULT 'untitled',
    score integer NOT NULL DEFAULT 0,
    note text,
    secret text NOT NULL DEFAULT 'private'
);
